// Content with portions generated by generative AI platform

package org.eclipse.kura.util.zip;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeFalse;

import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.ProcessBuilder.Redirect;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import org.apache.commons.io.FileUtils;
import org.apache.commons.io.IOUtils;
import org.eclipse.kura.KuraException;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * Covers {@link UnZip#main(String[])}, the entry point the extraction process runs. The process is really spawned
 * and really terminated, since the behaviour under test is what its shutdown hook does when the extraction is cut
 * short, for instance by the extraction timeout.
 */
public class CleanUpAfterKilledExtractionTest {

    private static final String WORK_FOLDER = "/tmp/kura_killed_extraction_test/";
    private static final String OUTPUT_FOLDER = WORK_FOLDER + "out";
    private static final String PRESERVED_FILE = "keepme.txt";

    private static final int ENTRY_COUNT = 400;
    private static final int TERMINATION_TIMEOUT_SECONDS = 30;
    private static final int EXTRACTION_START_TIMEOUT_MILLIS = 20000;

    private byte[] archive;
    private Process extractionProcess;
    private boolean processTerminated;
    private int exitCode;
    private String processOutput = "";

    @Before
    public void checkTerminationIsDelivered() {
        assumeFalse("the extraction process must be terminated with a signal for its shutdown hook to run",
                System.getProperty("os.name").toLowerCase().contains("win"));
    }

    @After
    public void clean() throws IOException {
        if (this.extractionProcess != null && this.extractionProcess.isAlive()) {
            this.extractionProcess.destroyForcibly();
        }

        FileUtils.deleteDirectory(new File(WORK_FOLDER));
    }

    @Test
    public void extractedFilesAreKeptWhenTheProcessCompletes() throws Exception {
        givenArchiveWithEntryCount(ENTRY_COUNT);
        givenAnExtractionProcessExtractingIn(OUTPUT_FOLDER);

        whenTheWholeArchiveIsSentToTheProcess();
        whenTheProcessCompletes();

        thenTheProcessTerminated();
        thenTheProcessSucceeded();
        thenFolderContainsFileCount(OUTPUT_FOLDER, ENTRY_COUNT);
    }

    @Test
    public void noFilesLeftBehindWhenTheProcessIsKilled() throws Exception {
        givenArchiveWithEntryCount(ENTRY_COUNT);
        givenAnExtractionProcessExtractingIn(OUTPUT_FOLDER);
        givenTheProcessHasStartedExtracting();

        whenTheProcessIsTerminated();

        thenTheProcessTerminated();
        thenFolderDoesNotExist(OUTPUT_FOLDER);
    }

    @Test
    public void preexistingFilesArePreservedWhenTheProcessIsKilled() throws Exception {
        givenArchiveWithEntryCount(ENTRY_COUNT);
        givenExistingOutputFolderContaining(PRESERVED_FILE);
        givenAnExtractionProcessExtractingIn(OUTPUT_FOLDER);
        givenTheProcessHasStartedExtracting();

        whenTheProcessIsTerminated();

        thenTheProcessTerminated();
        thenFolderContainsOnly(OUTPUT_FOLDER, PRESERVED_FILE);
    }

    @Test
    public void outputFolderIsRequired() throws Exception {
        givenAnExtractionProcessWithoutAnOutputFolder();

        whenTheProcessCompletes();

        thenTheProcessTerminated();
        thenTheProcessFailed();
        thenTheProcessOutputContains("Usage:");
    }

    private void givenArchiveWithEntryCount(int entryCount) throws IOException {
        this.archive = TestZipArchives.withEntryCount(entryCount);
    }

    private void givenExistingOutputFolderContaining(String fileName) throws IOException {
        FileUtils.writeStringToFile(new File(OUTPUT_FOLDER + File.separator + fileName), "do not delete me", "UTF-8");
    }

    private void givenAnExtractionProcessExtractingIn(String outputFolder) throws Exception {
        startExtractionProcess(outputFolder);
    }

    private void givenAnExtractionProcessWithoutAnOutputFolder() throws Exception {
        startExtractionProcess();
    }

    /**
     * Sends only part of the archive and leaves the standard input open, so that the process is certainly still
     * extracting when it is terminated.
     */
    private void givenTheProcessHasStartedExtracting() throws Exception {
        OutputStream processInput = this.extractionProcess.getOutputStream();
        processInput.write(this.archive, 0, this.archive.length / 2);
        processInput.flush();

        waitUntilTheOutputFolderIsNotEmpty();
    }

    private void whenTheWholeArchiveIsSentToTheProcess() throws IOException {
        try (OutputStream processInput = this.extractionProcess.getOutputStream()) {
            processInput.write(this.archive);
        }
    }

    private void whenTheProcessCompletes() throws Exception {
        awaitProcessTermination();
    }

    private void whenTheProcessIsTerminated() throws Exception {
        this.extractionProcess.destroy();

        awaitProcessTermination();
    }

    private void thenTheProcessTerminated() {
        assertTrue("the extraction process did not terminate", this.processTerminated);
    }

    private void thenTheProcessSucceeded() {
        assertEquals("the extraction process failed: " + this.processOutput, 0, this.exitCode);
    }

    private void thenTheProcessFailed() {
        assertNotEquals(0, this.exitCode);
    }

    private void thenTheProcessOutputContains(String content) {
        assertTrue("'" + this.processOutput + "' does not contain '" + content + "'",
                this.processOutput.contains(content));
    }

    private void thenFolderDoesNotExist(String folder) {
        assertFalse(new File(folder).exists());
    }

    private void thenFolderContainsFileCount(String folder, int expectedFileCount) {
        File outputFolder = new File(folder);
        assertTrue(folder + " does not exist", outputFolder.isDirectory());

        assertEquals(expectedFileCount, outputFolder.list().length);
    }

    private void thenFolderContainsOnly(String folder, String... expectedFileNames) {
        File outputFolder = new File(folder);
        assertTrue(outputFolder.isDirectory());

        assertArrayEquals(expectedFileNames, outputFolder.list());
    }

    private void startExtractionProcess(String... arguments) throws Exception {
        List<String> commandLine = new ArrayList<>();
        commandLine.add(System.getProperty("java.home") + File.separator + "bin" + File.separator + "java");
        commandLine.add("-cp");
        commandLine.add(extractionClassPath());
        commandLine.add(UnZip.class.getName());
        commandLine.addAll(List.of(arguments));

        this.extractionProcess = new ProcessBuilder(commandLine).redirectErrorStream(true)
                .redirectOutput(Redirect.PIPE).start();
    }

    private void awaitProcessTermination() throws Exception {
        this.processOutput = IOUtils.toString(this.extractionProcess.getInputStream(), StandardCharsets.UTF_8);
        this.processTerminated = this.extractionProcess.waitFor(TERMINATION_TIMEOUT_SECONDS, TimeUnit.SECONDS);

        if (this.processTerminated) {
            this.exitCode = this.extractionProcess.exitValue();
        }
    }

    private void waitUntilTheOutputFolderIsNotEmpty() throws InterruptedException {
        File outputFolder = new File(OUTPUT_FOLDER);
        long deadline = System.currentTimeMillis() + EXTRACTION_START_TIMEOUT_MILLIS;

        while (System.currentTimeMillis() < deadline) {
            String[] extracted = outputFolder.list();
            if (extracted != null && extracted.length > 1) {
                return;
            }

            Thread.sleep(50);
        }

        throw new IllegalStateException("the extraction process did not extract anything within the expected time");
    }

    private static String extractionClassPath() {
        return Stream.of(UnZip.class, KuraException.class).map(CleanUpAfterKilledExtractionTest::codeSourceOf)
                .distinct().collect(Collectors.joining(File.pathSeparator));
    }

    private static String codeSourceOf(Class<?> clazz) {
        try {
            return Paths.get(clazz.getProtectionDomain().getCodeSource().getLocation().toURI()).toString();
        } catch (URISyntaxException e) {
            throw new IllegalStateException("unable to locate the archive providing " + clazz.getName(), e);
        }
    }
}
